# Databricks notebook source
# MAGIC %md
# MAGIC # M69: bounded T4 interruption and Volume checkpoint recovery
# MAGIC Standalone manufactured engineering check; not scientific training.
# MAGIC Keep INSPECT_ONLY until the owner approves this exact release separately.
# MAGIC M68's spent approval does not apply. Never delete artifacts to rerun.
# MAGIC Only cuda:0 is used, but the entire existing four-T4 cluster is billable.
# MAGIC No installation, cluster-setting change, or idle-termination change.

# COMMAND ----------
import base64
import hashlib
import io
import json
import os
from pathlib import Path
import resource
import shutil
import signal
import subprocess
import sys
import tempfile
import time
import traceback
import zipfile

RELEASE_SHA256 = "e4d5157c50fa53a3472c1699143ea97257acc2059f2443b3291aab24b1521b6d"
RELEASE_BYTES_B64 = ""
READER_ZIP_B64 = ""
PREFIX = "followup/2026-10-19-m69-t4-recovery-qualification"
M68_PREFIX = "followup/2026-10-19-m68-uuid-repair"
ACK = "RUN ONE BOUNDED M69 T4 VOLUME RECOVERY QUALIFICATION"


def export_payload_upper(pre_export_bytes, encoded_name_lengths, remote_checkpoint_upper):
    framing = 22+sum(76+2*length for length in encoded_name_lengths)+2*(76+2*512)
    return 3*(pre_export_bytes+framing)+remote_checkpoint_upper+1024**2

dbutils.widgets.dropdown("MODE", "INSPECT_ONLY", ["INSPECT_ONLY", "RUN_ONCE"])
dbutils.widgets.text("ACKNOWLEDGEMENT", "")
dbutils.widgets.text("APPROVED_RELEASE_SHA256", "")
dbutils.widgets.text("OUTPUT_ZIP", "/Volumes/development/team_eds_supplychain/b08_runtime_output/m69-t4-recovery-001.zip")

# COMMAND ----------
def run_m69_notebook():
    release_bytes = base64.b64decode(RELEASE_BYTES_B64, validate=True)
    if hashlib.sha256(release_bytes).hexdigest() != RELEASE_SHA256:
        raise ValueError("EMBEDDED_RELEASE_MISMATCH")
    release = json.loads(release_bytes)
    mode = dbutils.widgets.get("MODE")
    if mode == "INSPECT_ONLY":
        return dict(decision="INSPECTION_ONLY_GPU_RUN_NOT_AUTHORIZED", release_sha256=RELEASE_SHA256,
            required_acknowledgement=ACK, approved_release_field_required=True, previous_approval_applies=False,
            planned_device="cuda:0", planned_maximum_run_seconds=1800, planned_jobs=40,
            scope="MANUFACTURED_INTERRUPTION_AND_UC_VOLUME_FRESH_PROCESS_RECOVERY_ONLY",
            files_written=False, gpu_queried=False, torch_imported=False, packages_installed=False,
            next_action="Return this inspection result. Wait for separate exact-release approval before RUN_ONCE.")
    if (mode != "RUN_ONCE" or dbutils.widgets.get("ACKNOWLEDGEMENT") != ACK
            or dbutils.widgets.get("APPROVED_RELEASE_SHA256") != RELEASE_SHA256):
        raise ValueError("SEPARATE_EXACT_RELEASE_ONE_SHOT_APPROVAL_REQUIRED")
    output = Path(dbutils.widgets.get("OUTPUT_ZIP"))
    if (not output.is_absolute() or ".." in output.parts or not str(output).startswith("/Volumes/")
            or output.suffix != ".zip" or len(output.parts) < 6):
        raise ValueError("EXISTING_UC_VOLUME_AND_NEW_ZIP_LEAF_REQUIRED")
    if not output.stem or len(output.stem) > 50 or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789-" for c in output.stem):
        raise ValueError("SAFE_NEW_PREFIX_REQUIRED")
    started, cpu = time.monotonic(), time.process_time()
    children_start = resource.getrusage(resource.RUSAGE_CHILDREN)
    def totals():
        children = resource.getrusage(resource.RUSAGE_CHILDREN)
        own = time.process_time()-cpu
        return dict(elapsed_seconds=time.monotonic()-started, wrapper_cpu_seconds=own,
                    aggregate_cpu_seconds=own+children.ru_utime+children.ru_stime-children_start.ru_utime-children_start.ru_stime)
    if shutil.disk_usage("/tmp").free < 2*1024**3+256*1024**2:
        raise ValueError("SCRATCH_RESERVE_REQUIRED")
    archive_bytes = base64.b64decode(READER_ZIP_B64, validate=True)
    if len(archive_bytes) > 8*1024**2 or hashlib.sha256(archive_bytes).hexdigest() != release["archive_sha256"]:
        raise ValueError("EMBEDDED_ARCHIVE_MISMATCH")
    with zipfile.ZipFile(io.BytesIO(archive_bytes)) as archive:
        if len(archive.infolist()) != len(release["members"]) or set(archive.namelist()) != set(release["members"]):
            raise ValueError("CURATED_MEMBER_ROSTER_MISMATCH")
        payloads = {}
        for name, binding in release["members"].items():
            if Path(name).is_absolute() or ".." in Path(name).parts or binding["size_bytes"] > 8*1024**2:
                raise ValueError("UNSAFE_MEMBER")
            value = archive.read(name)
            if len(value) != binding["size_bytes"] or hashlib.sha256(value).hexdigest() != binding["sha256"]:
                raise ValueError("MEMBER_HASH_MISMATCH")
            payloads[name] = value
    root = Path(tempfile.mkdtemp(prefix="m69-t4-"))
    source, delivery, attempt = root/"source", root/"delivery", root/"recovery-attempt-001"
    source.mkdir(); delivery.mkdir()
    for name, value in payloads.items():
        path = source/name
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("xb") as stream:
            stream.write(value)
    (delivery/"release.json").write_bytes(release_bytes)
    (delivery/"reader.zip").write_bytes(archive_bytes)
    code, old = source/PREFIX, source/M68_PREFIX
    contract = {}
    exec(compile(payloads[PREFIX+"/contract.py"], "<verified-m69-contract>", "exec"), contract)
    custody = {"__name__": "verified_m69_custody"}
    exec(compile(payloads[M68_PREFIX+"/process_custody.py"], "<verified-custody>", "exec"), custody)
    approval = dict(schema="m69-one-shot-approval-v1", approved=True, release_sha256=RELEASE_SHA256,
        acknowledgement=ACK, device="cuda:0", attempt=str(attempt), limits=contract["CUDA_LIMITS"],
        existing_four_t4_cluster_billable=True, automatic_retry=False)
    (root/"approval.json").write_text(json.dumps(approval, sort_keys=True)+"\n")
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1", PYTHONHASHSEED="0")
    def terminate(proc):
        if proc.poll() is None:
            try:
                os.killpg(proc.pid, signal.SIGTERM)
            except ProcessLookupError:
                proc.wait(timeout=3)
                return
            try:
                proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                proc.wait(timeout=3)
    def command(label, argv, seconds):
        with (root/(label+".stdout")).open("xb") as out, (root/(label+".stderr")).open("xb") as err:
            proc = subprocess.Popen(argv, env=env, stdout=out, stderr=err, start_new_session=True)
            try:
                proc.wait(timeout=max(1, seconds))
            finally:
                terminate(proc)
        return proc.returncode
    def control(operation, value):
        remaining = 1790-totals()["elapsed_seconds"]
        if remaining < 5 or totals()["aggregate_cpu_seconds"]+3 > 1800:
            raise RuntimeError("CONTROL_BUDGET_EXHAUSTED_PRESERVE:"+str(root))
        payload = root/(operation+"-payload.json")
        payload.write_text(json.dumps(value, sort_keys=True, allow_nan=False)+"\n")
        rc = command(operation, [sys.executable, "-B", str(code/"control_io.py"), operation,
            str(output), str(payload), str(old)], min(10, remaining))
        if rc != 0:
            raise RuntimeError("CONTROL_IO_FAILED_NO_RETRY:"+operation+":"+str(root))
    control("intent", dict(release_sha256=RELEASE_SHA256, acknowledgement=ACK, output=str(output),
                           automatic_retry=False, started_utc_epoch=time.time()))
    error, rc, cleanup = None, None, None
    try:
        if 1650-totals()["elapsed_seconds"] < 5 or totals()["aggregate_cpu_seconds"]+1500 > 1750:
            raise RuntimeError("NO_SUPERVISOR_BUDGET_PRESERVE_NO_RETRY")
        rc = command("supervisor", [sys.executable, "-B", str(code/"supervisor.py"), "--repo", str(source),
            "--release", str(delivery/"release.json"), "--expected-release-sha256", RELEASE_SHA256,
            "--attempt", str(attempt), "--mode", "CUDA", "--volume-parent", str(output.parent),
            "--volume-prefix", output.stem, "--approval", str(root/"approval.json")], 1650-totals()["elapsed_seconds"])
    except BaseException:
        error = traceback.format_exc()
    finally:
        if attempt.is_dir():
            try:
                cleanup = custody["cleanup_attempt"](attempt)
                (root/"child-cleanup.json").write_text(json.dumps(cleanup, sort_keys=True)+"\n")
            except BaseException:
                error = (error or "")+traceback.format_exc()
    accounting = dict(totals(), supervisor_returncode=rc, error=error, child_cleanup=cleanup,
                      automatic_retry=False, local_evidence=str(root))
    (root/"wrapper-accounting-before-export.json").write_text(json.dumps(accounting, sort_keys=True)+"\n")
    remaining = 1780-totals()["elapsed_seconds"]
    if remaining < 5 or totals()["aggregate_cpu_seconds"]+21 > 1800:
        raise RuntimeError("NO_EXPORT_BUDGET_PRESERVED_LOCAL:"+str(root))
    remote_checkpoint_upper = 36*(2*1024**2+65536)+4096
    export_files = [p for p in root.rglob("*") if p.is_file()]
    pre_export_bytes = sum(p.stat().st_size for p in export_files)
    # ZIP_STORED: 30-byte local header + 46-byte central entry + two
    # filename copies; 22-byte end record. Reserve two new export log entries.
    export_upper = export_payload_upper(pre_export_bytes,
        [len(p.relative_to(root).as_posix().encode()) for p in export_files], remote_checkpoint_upper)
    if (any(p.is_symlink() for p in export_files) or len(export_files) > 4096
            or any(len(p.relative_to(root).as_posix().encode()) > 512 for p in export_files)
            or pre_export_bytes > 80*1024**2
            or export_upper > 256*1024**2):
        raise RuntimeError("PRE_EXPORT_TOTAL_EVIDENCE_BOUND_PRESERVED_LOCAL:"+str(root))
    exported_rc = command("export", [sys.executable, "-B", str(old/"export_evidence.py"), str(root), str(output)], min(60, remaining))
    if exported_rc:
        raise RuntimeError("EXPORT_FAILED_NO_RETRY_LOCAL_EVIDENCE:"+str(root))
    exported = json.loads((root/"export.stdout").read_text())
    check_path = attempt/"jobs"/"040-saved-checker"/"receipt.json"
    checked = json.loads(check_path.read_text()) if check_path.is_file() else None
    local_bytes = sum(p.stat().st_size for p in root.rglob("*") if p.is_file())
    # Conservative upper bound for all 36 possible generation writes, including
    # interrupted writes; not a physical provider storage/billing measurement.
    accounting.update(totals(), local_payload_bytes=local_bytes, exported_payload_bytes=exported["size_bytes"],
                      remote_checkpoint_payload_upper_bytes=remote_checkpoint_upper,
                      export_sha256=exported["sha256"])
    accounting["within_limits"] = (accounting["elapsed_seconds"] <= 1800 and accounting["aggregate_cpu_seconds"] <= 1800
        and accounting["wrapper_cpu_seconds"] <= 30 and local_bytes+exported["size_bytes"]+remote_checkpoint_upper <= 256*1024**2)
    accounting["measurement_scope"] = "THROUGH_EXPORT_BEFORE_FINAL_CONTROL_IO"
    accounting["final_wrapper_acceptance_claimed"] = False
    control("completion", accounting)
    accounting.update(totals())
    accounting["measurement_scope"] = "THROUGH_FINAL_CONTROL_IO"
    accounting["within_limits"] = accounting["within_limits"] and accounting["elapsed_seconds"] <= 1800 and accounting["aggregate_cpu_seconds"] <= 1800 and accounting["wrapper_cpu_seconds"] <= 30
    passed = (rc == 0 and error is None and cleanup is not None and cleanup.get("all_terminated") is True
              and checked is not None and checked.get("decision") == "PASS_M69_SELECTED_T4_VOLUME_RECOVERY_ONLY" and accounting["within_limits"])
    return dict(decision="RESULT_REQUIRES_REVIEW" if passed else "STOP_REVIEW_PRESERVED_EVIDENCE",
        checker=checked, resources=accounting, evidence_zip=str(output), evidence_sha256=exported["sha256"],
        local_preserved_evidence=str(root), release_sha256=RELEASE_SHA256, automatic_retry=False,
        scientific_training=False, cluster_settings_changed=False, M69_closed_by_notebook=False)

print(json.dumps(run_m69_notebook(), sort_keys=True, indent=2, allow_nan=False))
